$('import').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>100000)throw Error('Arquivo muito grande');const data=JSON.parse(await file.text());if(data.version!==2||!Array.isArray(data.completed)||!data.completed.every(id=>typeof id==='string'&&valid.has(id)))throw Error('Formato incompatível');if(data.completed.length>tasks.length)throw Error('Backup contém itens demais');if(!confirm('A importação substituirá seu progresso atual ('+done.size+' competências). Continuar?')){message('Importação cancelada.');return}done=new Set(data.completed);save();render();message(storageAvailable?'Backup importado e salvo.':'Backup importado apenas nesta sessão; exporte uma cópia.')}catch(err){message('Erro: '+err.message)}finally{e.target.value=''}});
$('reset').addEventListener('click',()=>{if(confirm('Apagar o progresso deste navegador?')){done.clear();save();render();message('Progresso zerado.')}});
